scenes.code:
var B=kit.realBody({});
ui.button('جهاز الهضم',function(){B.show('dig');ui.result('جهاز الهضم: يحلّل الغذاء ليستفيد منه الجسم')});
ui.button('الجهاز التنفسي',function(){B.show('resp');ui.result('الجهاز التنفسي: يزوّد الجسم بالأكسجين')});
ui.button('جهاز الدوران',function(){B.show('circ');ui.result('جهاز الدوران: القلب والأوعية تنقل الغذاء والأكسجين والفضلات')});
ui.button('الكل',function(){B.show('all');ui.result('الأجهزة الثلاثة تعمل معاً في جسمك')});
ui.result('هذه أعضاء حقيقية من جسم الإنسان — اضغط على جهاز لتراه وحده');

var Sp=kit.sponge({});var p=Sp.points;
addLabel('ثقوب صغيرة يدخل منها الماء',p.pore[0],p.pore[1],p.pore[2]);
addLabel('التجويف الداخلي',p.cavity[0],p.cavity[1],p.cavity[2]);
addLabel('الفتحة العليا: يخرج منها الماء',p.top[0],p.top[1],p.top[2]);
addLabel('الخلايا تلتقط الغذاء',p.wall[0],p.wall[1],p.wall[2]);
ui.button('تيار أقوى 💧',function(){Sp.fast();ui.result('يدخل الماء من الثقوب، وتلتقط الخلايا الغذاء الأخضر، ثم يخرج الماء من الأعلى')});
ui.result('الأزرق: ماء · الأخضر: غذاء عالق في الماء');

var O=kit.oneOpening({});var p=O.points;
addLabel('الهيدرا (من اللاسعات)',p.hydra[0],p.hydra[1],p.hydra[2]);
addLabel('الفم: فتحة واحدة',p.hMouth[0]-.9,p.hMouth[1],p.hMouth[2]);
addLabel('التجويف الهضمي',p.hCavity[0]-.9,p.hCavity[1],p.hCavity[2]);
addLabel('دودة مفلطحة (البلاناريا)',p.planaria[0],p.planaria[1]+.6,p.planaria[2]);
addLabel('البلعوم: الفتحة الوحيدة',p.pharynx[0]+.4,p.pharynx[1]+.4,p.pharynx[2]);
addLabel('تجويف هضمي متفرّع',p.pGut[0]-.6,p.pGut[1]+.3,p.pGut[2]);
ui.button('أطعمهما 🦐',O.feed);
ui.result('اضغط «أطعمهما» وتابع الغذاء');

kit.ground({color:'#c79a66',color2:'#b3864f',size:16,flat:5});
var W=kit.worm({});var p=W.points;
addLabel('الفم',p.mouth[0],p.mouth[1]+.5,p.mouth[2]);
addLabel('المريء',p.esophagus[0],p.esophagus[1]+.7,p.esophagus[2]);
addLabel('الحويصلة: تخزّن',p.crop[0],p.crop[1]+1.1,p.crop[2]);
addLabel('القانصة: تطحن',p.gizzard[0]+.3,p.gizzard[1]-.7,p.gizzard[2]);
addLabel('المعى: يهضم ويمتص',p.intestine[0],p.intestine[1]+.7,p.intestine[2]);
addLabel('فتحة الإخراج',p.anus[0],p.anus[1]+.5,p.anus[2]);
kit.view(0,3.4,6.2,0,.5,0);
ui.button('أطعم الدودة 🌱',function(){W.feed();ui.result('الغذاء الأخضر يدخل من الفم، ويخرج فضلات بنية من فتحة الإخراج')});

var D=kit.realDigestive({});
ui.button('ابدأ رحلة الغذاء 🍎',D.start);
ui.result('اضغط لتتابع رحلة الغذاء من الفم عضواً بعد عضو');

var T=kit.paperTest({});
ui.button('اغمس الأشرطة',T.dip);
ui.button('أعد التجربة',T.reset);

var E=kit.realExcretion({});
ui.button('الجلد 💧',function(){E.show('skin');ui.result('الجلد: يطرد الماء الزائد والأملاح على شكل العرق')});
ui.button('الكبد',function(){E.show('liver');ui.result('الكبد: يعمل كمصفاة تجهّز الفضلات للطرد')});
ui.button('الكليتان',function(){E.show('kidney');ui.result('الكليتان: تطردان الفضلات السائلة (البول) عبر الحالبين إلى المثانة')});
ui.button('الرئتان',function(){E.show('lungs');ui.result('الرئتان: تطردان ثاني أكسيد الكربون وبخار الماء مع الزفير')});
ui.button('الأمعاء الغليظة',function(){E.show('colon');ui.result('الأمعاء الغليظة: تطرد الفضلات الصلبة')});
ui.button('الكل',function(){E.show('all');ui.result('خمسة أعضاء تخلّص الجسم من الفضلات')});
ui.result('اضغط على عضو لترى ما يطرده');

var Lg=kit.realLungs({});
ui.slider('سرعة التنفس',8,40,14,1,'نفَس/د',function(v){Lg.setRate(v)});
ui.button('ركض 🏃',function(){Lg.setRate(36);ui.result('أثناء الركض نتنفس أسرع لنحصل على أكسجين أكثر')});
ui.button('راحة',function(){Lg.setRate(14);ui.result('في الراحة نتنفس بهدوء')});
ui.result('شهيق: الحجاب الحاجز ينزل فتتمدد الرئتان — الأزرق أكسجين داخل');

var A=kit.alveoli({});
var p=A.points;
addLabel('شعيبة هوائية',p.bronchiole[0]+.4,p.bronchiole[1],p.bronchiole[2]);
addLabel('حويصلة هوائية',p.alveolus[0]+.3,p.alveolus[1],p.alveolus[2]);
addLabel('شعيرة دموية',p.capillary[0],p.capillary[1],p.capillary[2]);
addLabel('الأكسجين ← إلى الدم',-1.9,-.1,.6);
addLabel('ثاني أكسيد الكربون ← إلى الخارج',1.6,3.4,.4);
ui.button('شهيق عميق',function(){A.o2.rate=90;setTimeout(function(){A.o2.rate=26},2500);ui.result('دخل أكسجين أكثر فانتقل إلى الدم عبر الجدران الرقيقة')});
ui.result('الأزرق: أكسجين يدخل الدم · الرمادي: ثاني أكسيد الكربون يخرج');

var O=kit.openClosed({});
var p=O.points;
addLabel('القلب الأنبوبي (على الظهر)',p.dorsal[0],p.dorsal[1],p.dorsal[2]);
addLabel('الدم يخرج ويغمر الأعضاء',p.sinus[0],p.sinus[1],p.sinus[2]);
addLabel('القلب',p.heartB[0],p.heartB[1],p.heartB[2]);
addLabel('الخياشيم: يأخذ الدم الأكسجين',p.gills[0],p.gills[1],p.gills[2]);
addLabel('أوعية إلى الجسم',p.body[0],p.body[1],p.body[2]);
ui.result('المفتوح: الدم يخرج من الأوعية إلى الأنسجة · المغلق: الدم داخل الأوعية دائماً');

var Cc=kit.circulation({});
var p=Cc.points;
addLabel('القلب',p.heart[0],p.heart[1],p.heart[2]);
addLabel('الرئة',p.lungL[0],p.lungL[1],p.lungL[2]);
addLabel('الرئة',p.lungR[0],p.lungR[1],p.lungR[2]);
addLabel('خلايا الجسم',p.body[0]+1.9,p.body[1]+.3,p.body[2]);
addLabel('شريان',p.artery[0]+.3,p.artery[1],p.artery[2]);
addLabel('وريد',p.vein[0]-.3,p.vein[1],p.vein[2]);
addLabel('شعيرات دموية',p.capLung[0],p.capLung[1],p.capLung[2]);
kit.view(0,2.1,11,0,1.75,0);
ui.slider('نبض القلب',50,150,72,1,'نبضة/د',function(v){Cc.setRate(v)});
ui.button('تتبّع خلية دم 🔴',Cc.follow);
ui.result('الأحمر: دم مؤكسج · الأزرق: دم غير مؤكسج');
